function registerRows(){return Object.entries(DICTIONARY).filter(([key,d])=>(state.group==='all'||d.group===state.group)&&`${key} ${d.label} ${state.deal.assumptions[key].source}`.toLowerCase().includes(state.filter.toLowerCase())).map(([key,d])=>{const a=state.deal.assumptions[key],v=a.value;return `<tr><td><strong>${esc(d.label)}</strong><div style="margin-top:5px"><small>${key} · ${d.group}</small></div></td><td>${d.unit==='boolean'||d.unit==='enum'?`<select data-register="${key}">${selectOptions(key,v)}</select>`:`<input data-register="${key}" aria-label="${esc(d.label)}" type="${d.unit==='date'?'date':d.unit==='text'?'text':'number'}" step="any" value="${esc(v)}" placeholder="Missing / null">`}</td><td>${esc(d.unit)}<br><small>${d.currency??''}</small></td><td>${badge(v===null?'missing':a.status)}<select data-meta-status="${key}" aria-label="${key} status" style="margin-top:7px">${['contracted','observed','estimated','illustrative','missing'].map(s=>`<option ${a.status===s?'selected':''}>${s}</option>`).join('')}</select></td><td><input class="source-input" data-meta-source="${key}" aria-label="${key} source" value="${esc(a.source)}"><input type="date" data-meta-date="${key}" aria-label="${key} source date" value="${esc(a.sourceDate)}" style="margin-top:5px"></td></tr>`;}).join('');}
function renderSources(){return panel('Source audit','Read-only snapshot preserved. Live source comparison completed 30 October 2026 UTC.',`<div class="audit-grid"><div><h3>Reusable project economics</h3><p>2,880 billed GB300 GPUs across 40 active racks. Standard equipment: $280m. Throttled equipment: $240m. Site NRC: $8.666667m. BOM including two spare racks and networking: $275.3608m.</p><p>Standard: $5.80/GPU-hour and 6.5 MW. Throttled: $4.90/GPU-hour and 4.8 MW. Bundled DC rate: $270/kW/month. These are historical estimates, not signed terms.</p><a href="docs/SOURCE_AUDIT.md" target="_blank">Read full source audit ↗</a> · <a href="docs/FORMULAS.md" target="_blank">Formula documentation ↗</a></div><div><h3>Corrections & current-source comparison</h3><p>B31 is a cost/revenue ratio. Source-cost-only corrected DSCR: 1.1633× standard / 1.1839× throttled. J10 duplicates DC fees and omits NRC; sum period payments instead. J16 independently reconciles.</p><p>296 populated cells compared in bounded live reads. No material value differences. Two equivalent CEILING syntax differences. Live metadata modified: 20 Oct 2026 03:48:46 UTC. This check does not verify signed terms or edits outside the inspected range.</p><a href="data/source-snapshot.json" target="_blank">Snapshot cells + SHA-256 ↗</a> · <a href="data/live-source.json" target="_blank">Current source read ↗</a></div></div>`)+panel('Assumptions dictionary','Every field is editable. Empty values remain null. Numeric zero is a deliberate value; missing is explicitly labeled.',`<div class="filter-bar"><input id="register-search" type="search" placeholder="Find an input or source…" value="${esc(state.filter)}"><select id="register-group"><option value="all">All input groups</option>${[...new Set(Object.values(DICTIONARY).map(d=>d.group))].map(g=>`<option ${state.group===g?'selected':''}>${g}</option>`).join('')}</select><button class="btn" data-download="assumptions">Assumptions CSV ↓</button><button class="btn" id="import">Import review JSON ↑</button></div><div class="table-scroll input-register"><table><thead><tr><th>Input</th><th>Value</th><th>Unit / currency</th><th>Status</th><th>Source / date</th></tr></thead><tbody id="register-body">${registerRows()}</tbody></table></div><p class="chart-caption">Legal declarations need supporting documents. Setting a right to true is an input assertion, not a legal opinion. Separate fields cover power bundling, site scope, support availability and expiry. Illustrative zero costs are exclusions to revisit.</p>`)+panel('Source-to-formula mapping','The deterministic engine owns formulas; the interface only passes versioned inputs.',`<div class="table-scroll"><table class="source-mapping"><thead><tr><th>Source cells</th><th>New input / output</th><th>Formula / treatment</th></tr></thead><tbody>${FORMULA_MAPPING.map(m=>`<tr><td>${esc(m.source)}</td><td>${esc(m.input)}</td><td>${esc(m.formula)}</td></tr>`).join('')}</tbody></table></div>`);}
function renderSaved(){
 return panel('Frozen scenarios','Saved in this browser only. Each snapshot preserves inputs, source metadata, settings, hashes and the model version.',`<div class="inline-actions" style="margin-bottom:18px"><button class="btn dark" id="open-save">Freeze current scenario</button><button class="btn" id="import">Import review JSON ↑</button></div>${state.saved.length?state.saved.map((s,i)=>`<div class="saved-card"><div><h3>${esc(s.name)}</h3><small>${s.savedAt} · v${s.modelVersion} · ${s.inputHash}</small><small>Default: ${s.settings.defaultDate??'none'} · ${s.settings.defaultType} · ${STRATEGIES[s.settings.strategy].label}</small><div class="summary-line">Recovery ${pct(s.summary.recoveryPercent)} · shortfall ${money(s.summary.principalShortfall)} · XIRR ${pct(s.summary.irr)}</div></div><div class="inline-actions"><button class="btn" data-duplicate="${i}">Duplicate & edit</button><button class="btn" data-saved-export="${i}">Export</button><button class="text-btn" data-delete="${i}">Delete</button></div></div>`).join(''):'<div class="empty">No frozen scenarios yet. Save a working case to compare it here.</div>'}<p class="chart-caption">Standard and throttled source templates are immutable. Editing a duplicate creates a new working input version. Saved scenarios never mutate when sliders change.</p>`);
}
const shortStrategies={hold:'Hold & operate',restructure:'Restructure',release:'Re-lease',relocate:'Relocate',liquidate:'Liquidate'};
let compareOpen=false;
function renderSimple(){
 const r=state.data?.selected;
 if(!r){$('#simple-results').innerHTML='<div class="loading">Calculating…</div>';return;}
 if(!r.valid){$('#simple-results').innerHTML=`<div class="error-panel"><h2>Missing or invalid inputs</h2><p>${r.errors.map(esc).join('<br>')}</p><button class="btn" data-go="sources">Review inputs</button></div>`;return;}
 const s=r.summary,a=s.atDefault,hasDefault=!!state.settings.defaultDate,hasWorkout=hasDefault&&r.eligibility.status!=='not triggered',available=r.eligibility.status!=='unavailable',share=a.advanced?a.recovered/a.advanced:0;
 const context=hasDefault?`Just before ${shortDate(state.settings.defaultDate)}`:`At horizon · ${shortDate(s.horizon)}`;
 const further=Math.max(0,s.originalRecovered-a.recovered);
 $('#recovery-strategy').value=state.settings.strategy;$('#recovery-strategy').disabled=!hasWorkout;
 const chartSeries=[{key:'originalAdvanced',label:'Cash advanced',color:colors.advanced,dash:true},{key:'originalRecovered',label:'Principal recovered',color:colors.repaid},{key:'originalOutstanding',label:'Still at risk',color:colors.outstanding,fill:true,width:2.5}];
 const gap=s.maxCashGap>.01?`<p class="simple-alert">Unfunded cash gap: ${money(s.maxCashGap)}${s.firstGap?' · starts '+shortDate(s.firstGap):''}. No extra sponsor cash is assumed.</p>`:'';
 const coverage=s.minDscr!==null&&s.minDscr<1?`<p class="coverage-note">Minimum operating debt coverage: ${ratio(s.minDscr)}. <button class="text-btn" data-go="cashflows">View cash flows ↗</button></p>`:'';
 $('#simple-results').innerHTML=`<p class="as-of">${context} · original cash principal only</p>
 <div class="simple-metrics"><div><span>Cash advanced</span><strong>${money(a.advanced)}</strong></div><div><span>Already recovered</span><strong>${money(a.recovered)}</strong></div><div><span>Still at risk</span><strong>${money(a.exposure)}</strong></div></div>
 <section class="principal-chart" aria-label="Principal recovery chart"><div class="principal-chart-heading"><h2>Principal over time</h2><span>${pct(share)} recovered at selected date</span></div>${lineChart(r.monthly,chartSeries,{height:260})}${legend(chartSeries)}${a.fundedNotOperating>0?`<p class="chart-caption">${money(a.fundedNotOperating)} funded before operations at the selected date.</p>`:''}</section>
 <section class="simple-recovery"><div class="recovery-heading"><span>${hasWorkout?shortStrategies[state.settings.strategy]+' · projected recovery':hasDefault?'Contractual case · loan not accelerated':'Contractual case · no default'}</span><span class="recovery-status">${esc(r.eligibility.status)}</span></div>
 ${available?`<div class="recovery-answer"><div><strong>${money(s.originalRecovered)}</strong><span>projected total principal recovered</span></div><span class="recovery-percent">${pct(s.recoveryPercent)}</span></div><p class="recovery-subline">${hasDefault?`${money(further)} more after default · `:''}${money(s.principalShortfall)} unrecovered by ${shortDate(s.horizon)}</p><div class="recovery-facts"><span>Workout cash <b>${money(s.workoutAdvanced+s.additionalWorkoutCash)}</b></span><span>${hasWorkout?'Recovery receipt':'Full recovery'} <b>${hasWorkout?shortDate(s.recoveryReceiptDate):shortDate(s.milestones[100]?.date)}</b></span></div><p class="conditional-note">${r.eligibility.status==='conditional'?'Conditional estimate · legal rights and priority need evidence.':hasDefault&&!hasWorkout?'Buyer nonpayment does not accelerate this loan; contractual payments remain due.':hasDefault?'Projection depends on the stated costs, rights and timing.':'Projection from historical estimates and illustrative financing terms.'}</p>`:`<div class="unavailable-recovery"><strong>Unavailable</strong><p>${r.eligibility.reasons.map(esc).join(' ')}</p></div>`}</section>
 ${gap}${coverage}
 ${hasWorkout?`<details id="quick-compare" class="quick-compare" ${compareOpen?'open':''}><summary>Compare recovery options</summary><div class="table-scroll"><table><thead><tr><th>Option</th><th>Total principal</th><th>Workout cash</th><th>Receipt</th></tr></thead><tbody>${state.data.workouts.map(w=>{const t=w.summary,ok=w.valid&&w.eligibility.status!=='unavailable';return `<tr class="${w.settings.strategy===state.settings.strategy?'selected':''}"><td><button class="text-btn" data-strategy="${esc(w.settings.strategy)}">${shortStrategies[w.settings.strategy]}</button><small class="option-status">${esc(w.eligibility.status)}</small></td><td>${ok?money(t.originalRecovered):'Unavailable'}</td><td>${ok?money(t.workoutAdvanced+t.additionalWorkoutCash):'—'}</td><td>${ok?shortDate(t.recoveryReceiptDate):'—'}</td></tr>`;}).join('')}</tbody></table></div><button class="text-btn" data-go="workouts">Costs & eligibility details ↗</button></details>`:''}`;
 $('#quick-compare')?.addEventListener('toggle',e=>{compareOpen=e.target.open;});
}
function render(){
 renderSimple();
 const focused=document.activeElement,registerKey=focused?.dataset?.register,focusedValue=focused?.value,scrollTop=$('.input-register')?.scrollTop??0;
 $$('.tabbar button').forEach(b=>{b.classList.toggle('active',b.dataset.tab===state.tab);b.setAttribute('aria-selected',b.dataset.tab===state.tab);});
 if(!state.data){$('#results').innerHTML='<div class="loading">Calculating dated cash flows…</div>';return;}
 const r=state.data.selected;
 $('#run-meta').textContent=`MODEL ${MODEL_VERSION} · ${r.metadata.inputHash} · ${r.metadata.calculatedAt.slice(0,19)} UTC`;
 if(!$('#advanced-model').open)return;
 if(!r.valid&&state.tab!=='sources'){$('#results').innerHTML=`<div class="error-panel"><h2>Inputs need attention</h2>${r.errors.map(esc).join('<br>')}<br><button class="btn" data-go="sources">Open assumptions register</button></div>`;return;}
 $('#results').innerHTML=({overview:renderOverview,workouts:renderWorkouts,sensitivities:renderSensitivities,cashflows:renderCashflows,sources:renderSources,saved:renderSaved})[state.tab]();
 if(state.tab==='sources'&&registerKey){const input=$(`[data-register="${registerKey}"]`);if(input){input.value=focusedValue;input.focus({preventScroll:true});}if($('.input-register'))$('.input-register').scrollTop=scrollTop;}
 $('#run-meta').textContent=`MODEL ${MODEL_VERSION} · ${r.metadata.inputHash} · ${r.metadata.calculatedAt.slice(0,19)} UTC`;
}
