function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportCurrent(){if(!state.data?.selected.valid)return;const extras={scenarioComparisons:state.data.scenarios.map(r=>({name:r.name,summary:r.summary})),workoutComparisons:state.data.workouts,sensitivityGrids:state.grids,thresholdSearch:state.solver,structureSearch:state.structures,sourceAudit:'docs/SOURCE_AUDIT.md',sourceSnapshotSha256:'aefc0b4867c8eac903ef59f254315bafa99dcf9205565ee8e11471b197b12cf6'};download('OpenSilicon-'+state.deal.configuration+'-review.json',JSON.stringify(exportReviewPackage(state.deal,state.data.selected,extras),null,2));}
