function persistSaved(){try{localStorage.setItem(storageKey,JSON.stringify(state.saved));$('#saved-count').textContent=state.saved.length;return true;}catch{toast('Local storage is full. Export your review package to preserve it.');return false;}}
function freezeScenario(name){const result=state.data.selected,entry=freeze({name,savedAt:new Date().toISOString(),modelVersion:MODEL_VERSION,inputHash:hash(state.deal),resultHash:hash({ledger:result.ledger,summary:result.summary}),deal:structuredClone(state.deal),settings:{...state.settings},summary:structuredClone(result.summary)});state.saved=[...state.saved,entry];if(persistSaved()){toast('Scenario frozen. Further edits create a new working version.');if(state.tab==='saved')render();}}
document.addEventListener('input',e=>{
 const el=e.target;
  if(el.dataset.slider){const key=el.dataset.slider,value=['months','days'].includes(DICTIONARY[key].unit)?Math.round(Number(el.value)):Number(el.value);setInput(key,value);}
 if(el.dataset.number)setInput(el.dataset.number,el.value===''?null:fromDisplay(el.dataset.number,Number(el.value)));
 if(el.dataset.register&&el.tagName==='INPUT'){const key=el.dataset.register,d=DICTIONARY[key],v=el.value===''?null:['date','text'].includes(d.unit)?el.value:Number(el.value);setInput(key,v);}
 if(el.id==='default-month'){state.defaultMode='custom';state.settings.defaultDate=addMonths(values(state.deal).firstWire,Number(el.value));updateDefaultControls();invalidate();}
 if(el.id==='register-search'){state.filter=el.value;$('#register-body').innerHTML=registerRows();}
});
document.addEventListener('change',async e=>{
 const el=e.target;
 if(el.dataset.number&&el.value==='')setInput(el.dataset.number,null);
 if(el.dataset.simple||el.dataset.register){const key=el.dataset.simple||el.dataset.register,d=DICTIONARY[key],v=el.value===''||el.value==='null'?null:d.unit==='boolean'?el.value==='true':['date','text','enum'].includes(d.unit)?el.value:Number(el.value);setInput(key,v);}
 if(el.dataset.metaStatus||el.dataset.metaSource||el.dataset.metaDate){const key=el.dataset.metaStatus||el.dataset.metaSource||el.dataset.metaDate,a={...state.deal.assumptions[key]};if(el.dataset.metaStatus)a.status=el.value;if(el.dataset.metaSource)a.source=el.value;if(el.dataset.metaDate)a.sourceDate=el.value;setInput(key,a.value,a);}
 if(el.id==='configuration'){state.deal=TEMPLATES[el.value];state.settings.defaultDate=state.defaultMode==='none'?null:addMonths(values(state.deal).firstWire,12);state.defaultMode=state.defaultMode==='none'?'none':'12';renderControls();invalidate();}
 if(el.id==='default-date'){state.defaultMode='custom';state.settings.defaultDate=el.value||null;updateDefaultControls();invalidate();}
 if(el.id==='default-type'){state.settings.defaultType=el.value;invalidate();}
 if(el.id==='recovery-strategy'){state.settings.strategy=el.value;invalidate();}
 if(el.id==='register-group'){state.group=el.value;$('#register-body').innerHTML=registerRows();}
 if(el.id==='solve-key'){const bounds={ltv:[.2,.9],price:[0,12],resaleQuote:[0,values(state.deal).equipmentCost]};$('#solve-lower').value=bounds[el.value][0];$('#solve-upper').value=bounds[el.value][1];}
 if(el.id==='import-file'){
  try{const pkg=JSON.parse(await el.files[0].text()),deal=pkg.deal,settings=pkg.result?.settings??pkg.settings;if(pkg.modelVersion&&pkg.modelVersion!==MODEL_VERSION)throw new Error('Different model version');if(deal.modelVersion!==MODEL_VERSION)throw new Error('Different model version');const validation=validateInputs(deal);if(!validation.valid)throw new Error(validation.errors.join('; '));if(pkg.inputHash&&pkg.inputHash!==hash(deal))throw new Error('Input hash mismatch');state.deal=freeze(deal);state.settings={...settings};state.defaultMode=settings.defaultDate?'custom':'none';renderControls();invalidate();toast('Imported scenario. Recalculating the same dated engine.');}catch(error){toast('Import failed: '+error.message);}el.value='';
 }
});
document.addEventListener('click',e=>{
 const b=e.target.closest('button,a');if(!b)return;
 if(b.dataset.tab)go(b.dataset.tab);
 if(b.dataset.go)go(b.dataset.go);
 if(b.id==='audit-link'||b.id==='open-register'){e.preventDefault();go('sources');}
 if(b.id==='reset'){state.deal=TEMPLATES[state.deal.configuration];state.settings={defaultDate:addMonths(values(state.deal).firstWire,12),defaultType:'borrower',strategy:'liquidate'};state.defaultMode='12';$('#default-type').value='borrower';renderControls();invalidate();}
 if(b.dataset.default){state.defaultMode=b.dataset.default;state.settings.defaultDate=b.dataset.default==='none'?null:b.dataset.default==='custom'?(state.settings.defaultDate??addMonths(values(state.deal).firstWire,12)):addMonths(values(state.deal).firstWire,Number(b.dataset.default));updateDefaultControls();invalidate();}
 if(b.dataset.strategy){state.settings.strategy=b.dataset.strategy;invalidate();}
 if(b.id==='save'||b.id==='open-save')showSave();
 if(b.id==='confirm-save'){e.preventDefault();const name=$('#scenario-name').value.trim();if(!name)return;freezeScenario(name);$('#save-dialog').close();}
 if(b.id==='export')exportCurrent();
 if(b.id==='import')$('#import-file').click();
 if(b.dataset.ledgerView)$('#cash-table').innerHTML=cashFlowTable(b.dataset.ledgerView);
 if(b.dataset.download){const key=b.dataset.download,rows=key==='assumptions'?assumptionRows(state.deal):state.data.selected[key];download('OpenSilicon-'+key+'.csv',csv(rows),'text/csv');}
 if(b.dataset.duplicate!==undefined){const s=state.saved[Number(b.dataset.duplicate)];state.deal=overrideDeal(s.deal,{},s.name+' copy');state.settings={...s.settings};state.defaultMode=s.settings.defaultDate?'custom':'none';$('#default-type').value=state.settings.defaultType;renderControls();invalidate();go('overview');toast('Working duplicate created. Frozen original preserved.');}
 if(b.dataset.savedExport!==undefined){const s=state.saved[Number(b.dataset.savedExport)];download('OpenSilicon-frozen-scenario.json',JSON.stringify(s,null,2));}
 if(b.dataset.delete!==undefined){state.saved=state.saved.filter((_,i)=>i!==Number(b.dataset.delete));persistSaved();render();}
 if(b.id==='run-solver'){
  const key=$('#solve-key').value,lower=Number($('#solve-lower').value),upper=Number($('#solve-upper').value),steps=Number($('#solve-steps').value),constraints=$$('[data-constraint]:checked').map(x=>x.dataset.constraint);$('#solver-output').textContent='Searching bounded scenarios…';b.disabled=true;post('solve',{key,lower,upper,steps,direction:key==='ltv'?'max':'min',constraints},result=>{state.solver=result;if(state.tab==='sensitivities'){$('#solver-output').innerHTML=solverMarkup(result);$('#run-solver').disabled=false;}});
 }
 if(b.id==='run-structures'){
  b.disabled=true;const constraints=$$('[data-constraint]:checked').map(x=>x.dataset.constraint);$('#structures-output').textContent='Comparing 27 financing structures…';post('structures',{constraints},result=>{state.structures=result;if(state.tab==='sensitivities'){$('#structures-output').innerHTML=structuresMarkup(result);$('#run-structures').disabled=false;}});
 }
});
$('#advanced-model').addEventListener('toggle',()=>{if($('#advanced-model').open)render();});
window.addEventListener('hashchange',()=>{const tab=location.hash.slice(1);if(tab!==state.tab&&['overview','workouts','sensitivities','cashflows','sources','saved'].includes(tab)){state.tab=tab;$('#advanced-model').open=true;render();}});
if(['overview','workouts','sensitivities','cashflows','sources','saved'].includes(location.hash.slice(1))){state.tab=location.hash.slice(1);$('#advanced-model').open=true;}
renderControls();calculate();
